  const total=rows.reduce((a,c)=>({visits:a.visits+c.visits,orders:a.orders+c.orders,revenueMinor:a.revenueMinor+c.netRevenueMinor,costMinor:a.costMinor+c.costMinor}),{visits:0,orders:0,revenueMinor:0,costMinor:0});
